document.addEventListener("DOMContentLoaded", () => {
  const form = document.querySelector("form");
  const nomeInput = document.querySelector("#nome");
  const caInput = document.querySelector("#ca");
  const validadeInput = document.querySelector("#validade");
  const quantidadeInput = document.querySelector("#quantidade");
  const idInput = document.querySelector("input[name='id']");

  const btnEditList = document.querySelectorAll(".btn-edit");
  const btnDeleteList = document.querySelectorAll(".btn-delete");

  // 🟢 Quando clicar em "Editar", preenche o formulário com os dados da linha
  btnEditList.forEach(btn => {
    btn.addEventListener("click", event => {
      event.preventDefault();
      const row = btn.closest("tr");
      const nome = row.querySelector("td:nth-child(1)").textContent.trim();
      const ca = row.querySelector("td:nth-child(2)").textContent.trim();
      const validade = row.querySelector("td:nth-child(3)").textContent.trim();
      const quantidade = row.querySelector("td:nth-child(4)").textContent.trim();
      const href = btn.getAttribute("href");
      const id = href.split("/editar/")[1];

      nomeInput.value = nome;
      caInput.value = ca;
      validadeInput.value = validade;
      quantidadeInput.value = quantidade;
      idInput.value = id;

      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  });

  // 🔴 Confirmação customizada de exclusão
  btnDeleteList.forEach(btn => {
    btn.addEventListener("click", event => {
      const confirmDelete = confirm("Tem certeza que deseja excluir este EPI?");
      if (!confirmDelete) {
        event.preventDefault();
      }
    });
  });

  // 🧹 Reseta o formulário após envio
  form.addEventListener("submit", () => {
    setTimeout(() => {
      form.reset();
      idInput.value = "";
    }, 200);
  });
});
